    "_%n post in the last twelve weeks_::_%n posts in the last twelve weeks_" : ["%n embannadenn en daouzek sizhun ziwezhañ","%n embannadenn en daouzek sizhun ziwezhañ","%n embannadenn en daouzek sizhun ziwezhañ","%n a embannadennoù en daouzek sizhun ziwezhañ","%n embannadenn en daouzek sizhun ziwezhañ"],
    "_{count} post_::_{count} posts_" : ["{count} embannadenn","{count} embannadenn","{count} embannadenn","{count} a embannadennoù","{count} embannadenn"],
