    "_%n delivery has failed at least once._::_%n deliveries have failed at least once._" : ["%n gasadenn he deus c'hwitet ur wech da nebeutañ.","%n gasadenn o deus c'hwitet ur wech da nebeutañ.","%n c'hasadenn o deus c'hwitet ur wech da nebeutañ.","%n a gasadennoù o deus c'hwitet ur wech da nebeutañ.","%n kasadenn o deus c'hwitet ur wech da nebeutañ."],
