    "Go to Aloha Social app" : "Mont d'an arload Aloha Social",
    "_One account could not be reached from this server:_::_%n accounts could not be reached from this server:_" : ["%n gont n'eo ket bet tizhet diwar ar servijer-mañ:","%n gont n'int ket bet tizhet diwar ar servijer-mañ:","%n c'hont n'int ket bet tizhet diwar ar servijer-mañ:","%n a gontoù n'int ket bet tizhet diwar ar servijer-mañ:","%n kont n'int ket bet tizhet diwar ar servijer-mañ:"],
    "Add some with the starter_packs app setting, or read them in from other servers with starter_pack_sources." : "Ouzhpennit re gant an arventenn arload starter_packs, pe lennit anezho eus servijerioù all gant starter_pack_sources.",
    "This server does not suggest any starter packs yet." : "Ne ginnig ket ar servijer-mañ pakad loc'hañ ebet c'hoazh.",
    "Videos people are watching will appear here." : "Ar videoioù a sell an dud outo a zeuio war wel amañ.",
