    "_{tags} and %n more_::_{tags} and %n more_" : ["{tags} ha %n all","{tags} ha %n all","{tags} ha %n all","{tags} ha %n all","{tags} ha %n all"],
    "Why you're seeing this: interested in {tags}" : "Perak e welit an dra-mañ: dedennet gant {tags}",
    "Why you're seeing this: you follow {tags}" : "Perak e welit an dra-mañ: heuliañ a rit {tags}",
